const raw = $input.first().json;
const incident = raw.body || raw;

// --- Validation ---
const required = ['incidentId', 'severity', 'title', 'createdAt'];
const missing = required.filter(k => !incident[k]);
if (missing.length > 0) {
  return [{
    json: {
      _valid: false,
      error: `Missing required fields: ${missing.join(', ')}`,
      incidentId: incident.incidentId || 'unknown'
    }
  }];
}

const sevMap = { P1: 1, P2: 2, P3: 3, P4: 4 };
const severityRank = sevMap[incident.severity];
if (!severityRank) {
  return [{
    json: {
      _valid: false,
      error: `Invalid severity: ${incident.severity}. Expected P1-P4.`,
      incidentId: incident.incidentId
    }
  }];
}

// --- Normalize ---
const trunc = (s, n = 240) => (s || '').length > n ? s.slice(0, n - 3) + '...' : (s || '');
const correlationId = incident.metadata?.correlationId || '';
const dedupeKey = `${incident.incidentId}|${incident.severity}|${incident.title}`;
const ownerEmail = incident.ownerEmail || 'oncall@example.com';
const descriptionShort = trunc(incident.description, 240);

// --- Build Slack payload ---
const slackPayload = {
  channel: '#oncall-alerts',
  text: `[${incident.severity}] ${incident.incidentId} \u2014 ${incident.title} (corr=${correlationId})`
};

// --- Build O365 email payload ---
const emailPayload = {
  message: {
    subject: `[${incident.severity}] ${incident.incidentId} \u2014 ${incident.title}`,
    body: {
      contentType: 'Text',
      content: `${descriptionShort}\n\nCorrelationId: ${correlationId}\nCreatedAt: ${incident.createdAt}`
    },
    toRecipients: [{ emailAddress: { address: ownerEmail } }]
  },
  saveToSentItems: false
};

return [{
  json: {
    _valid: true,
    incidentId: incident.incidentId,
    severity: incident.severity,
    severityRank,
    title: incident.title,
    descriptionShort,
    correlationId,
    createdAt: incident.createdAt,
    ownerEmail,
    dedupeKey,
    slackPayload,
    emailPayload
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.failureLog) staticData.failureLog = [];

const data = $input.first().json;

staticData.failureLog.push({
  timestamp: new Date().toISOString(),
  incidentId: data.incidentId || 'unknown',
  channel: 'validation',
  error: data.error
});

return [{
  json: {
    status: 'error',
    reason: 'validation_failed',
    incidentId: data.incidentId || 'unknown',
    error: data.error
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.dedupeStore) staticData.dedupeStore = {};

const data = $input.first().json;
const isDuplicate = !!staticData.dedupeStore[data.dedupeKey];

return [{
  json: {
    ...data,
    _deduplicated: isDuplicate
  }
}];

const data = $input.first().json;

return [{
  json: {
    status: 'skipped',
    reason: 'duplicate',
    incidentId: data.incidentId,
    dedupeKey: data.dedupeKey,
    message: `Incident ${data.incidentId} already processed. Skipping.`
  }
}];

const axios = require('axios');

// --- Configuration ---
const MAX_ATTEMPTS = 5;
const BASE_DELAY_MS = 500;

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function shouldRetry(statusCode) {
  return statusCode === 429 || (statusCode >= 500 && statusCode <= 599);
}

async function sendWithRetry(url, token, payload, channelName) {
  let lastStatus = null;
  let lastBody = null;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      const res = await axios.post(url, payload, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        validateStatus: () => true
      });

      lastStatus = res.status;
      lastBody = res.data || null;

      // Success (2xx)
      if (res.status >= 200 && res.status < 300) {
        return {
          success: true,
          channel: channelName,
          status: res.status,
          body: lastBody,
          attempts: attempt
        };
      }

      // Non-retryable 4xx (except 429)
      if (!shouldRetry(res.status)) {
        return {
          success: false,
          channel: channelName,
          status: res.status,
          body: lastBody,
          attempts: attempt,
          retryable: false
        };
      }

      // Retryable (429 or 5xx) -- backoff before next attempt
    } catch (err) {
      lastBody = err.message;
    }

    if (attempt < MAX_ATTEMPTS) {
      const delay = BASE_DELAY_MS * Math.pow(2, attempt - 1);
      await sleep(delay);
    }
  }

  return {
    success: false,
    channel: channelName,
    status: lastStatus,
    body: lastBody,
    attempts: MAX_ATTEMPTS,
    exhausted: true
  };
}

// --- Execute both channels in parallel ---
const data = $input.first().json;

const [slackResult, o365Result] = await Promise.allSettled([
  sendWithRetry(
    'http://localhost:4010/chat.postMessage',
    'slack-test-token',
    data.slackPayload,
    'slack'
  ),
  sendWithRetry(
    'http://localhost:4020/me/sendMail',
    'ms-test-token',
    data.emailPayload,
    'o365'
  )
]);

return [{
  json: {
    ...data,
    slackResult: slackResult.status === 'fulfilled'
      ? slackResult.value
      : { success: false, channel: 'slack', error: slackResult.reason?.message },
    o365Result: o365Result.status === 'fulfilled'
      ? o365Result.value
      : { success: false, channel: 'o365', error: o365Result.reason?.message }
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.dedupeStore) staticData.dedupeStore = {};
if (!staticData.failureLog) staticData.failureLog = [];

const data = $input.first().json;
const slackOk = data.slackResult?.success === true;
const o365Ok = data.o365Result?.success === true;

// --- Persist failures ---
if (!slackOk) {
  staticData.failureLog.push({
    timestamp: new Date().toISOString(),
    incidentId: data.incidentId,
    dedupeKey: data.dedupeKey,
    channel: 'slack',
    lastStatus: data.slackResult?.status,
    attempts: data.slackResult?.attempts,
    error: data.slackResult?.body
  });
}
if (!o365Ok) {
  staticData.failureLog.push({
    timestamp: new Date().toISOString(),
    incidentId: data.incidentId,
    dedupeKey: data.dedupeKey,
    channel: 'o365',
    lastStatus: data.o365Result?.status,
    attempts: data.o365Result?.attempts,
    error: data.o365Result?.body
  });
}

// --- Record dedupe ONLY if both succeeded ---
if (slackOk && o365Ok) {
  staticData.dedupeStore[data.dedupeKey] = {
    processedAt: new Date().toISOString(),
    incidentId: data.incidentId
  };
}

return [{
  json: {
    status: slackOk && o365Ok ? 'success' : 'partial_failure',
    incidentId: data.incidentId,
    dedupeKey: data.dedupeKey,
    slack: slackOk ? 'sent' : 'failed',
    o365: o365Ok ? 'sent' : 'failed',
    slackResult: data.slackResult,
    o365Result: data.o365Result
  }
}];
